Method.Source:
[Form] 
public class FMVehicle extends FormRun
{ 
    NumberSeqFormHandler numberSeqFormHandler;

}

public void close()
{
    if (numberSeqFormHandler)
    {
        numberSeqFormHandler.formMethodClose();
    }

    super();
}

NumberSeqFormHandler numberSeqFormHandler()
{
    NumberSequenceReference reference;
    if (!numberSeqFormHandler)
    {
        reference = NumberSequenceReference::findByDatatypeAndScope(extendedtypenum(FMVehicleId));
        numberSeqFormHandler = NumberSeqFormHandler::newForm(reference.NumberSequenceId,
                                                             element,
                                                             FMVehicle_DS,
                                                             fieldNum(FMVehicle, VehicleId)
                                                            );
    }
    return numberSeqFormHandler;
}

public void init()
{
    QueryFilter qFilter;
    QueryBuildDataSource qbd;

    super();

    qbd = FMVehicle_DS.queryBuildDataSource();

    qFilter = FMVehicle_DS.query().addQueryFilter(qbd, fieldstr(FMVehicle, Description));
    qFilter = FMVehicle_DS.query().addQueryFilter(qbd, fieldstr(FMVehicle, Status));
    qFilter = FMVehicle_DS.query().addQueryFilter(qbd, fieldstr(FMVehicle, Mileage));
}

public void create(boolean _append = false)
{
    if (numberSeqFormHandler)
    {
        numberSeqFormHandler.formMethodDataSourceCreatePre();
    }

    super(_append);

    element.numberSeqFormHandler().formMethodDataSourceCreate(true);
}

public boolean validateWrite()
{
    boolean ret;

    ret = super();

    ret = element.numberSeqFormHandler().formMethodDataSourceValidateWrite(ret) && ret;

    return ret;
}

public void deleting()
{
    ttsbegin;
    element.numberSeqFormHandler().formMethodDataSourceDelete();
    super();
    ttscommit;
}

public void writing()
{
    ttsbegin;
    super();
    element.numberSeqFormHandler().formMethodDataSourceWrite();
    ttscommit;
}

public void modified()
{
    FMVehicleModel vehicleModel;
    FMModelRate modelRate;

    super();

    select firstonly * from vehicleModel where vehicleModel.RecId == FMVehicle.VehicleModel outer join modelRate where modelRate.MakeModelId == vehicleModel.RecId;

    FMVehicleModel_DS.cursor().data(vehicleModel);
    FMVehicleModel_DS.setCurrent();

    FMModelRate_DS.cursor().data(modelRate);
    FMModelRate_DS.setCurrent();
}
